```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorLabel ?deathDate
WHERE {
  VALUES (?film ?filmLabel) {
    (dbr:The_More_the_Merrier "The More the Merrier")
    (dbr:Sleep,_My_Love      "Sleep, My Love")
  }

  # director (prefer dbp:director, fallback to dbo:director)
  OPTIONAL { ?film dbp:director ?director . }
  OPTIONAL { ?film dbo:director ?director . }
  FILTER (BOUND(?director))

  # director label (English)
  OPTIONAL { ?director rdfs:label ?directorLabel .
             FILTER (lang(?directorLabel) = "en") }

  # death date (prefer dbp:deathDate, fallback to dbo:deathDate)
  OPTIONAL { ?director dbp:deathDate ?deathDateTmp . }
  OPTIONAL { ?director dbo:deathDate ?deathDateTmp2 . }
  BIND (COALESCE(?deathDateTmp, ?deathDateTmp2) AS ?deathDate)
}
LIMIT 100
```

